using System;
using System.Collections.Generic;
using Newtonsoft.Json;

namespace LastHearth.Core
{
    /// <summary>
    /// All numbers of the game. Generated by hearth/tools/economy.py into Resources/balance.json
    /// from the same model whose checks pass in docs/ECONOMY.md. Never edit the JSON by hand.
    /// </summary>
    public sealed class Balance
    {
        public int Version;
        public int MaxHearthLevel;
        public List<HearthLevelData> HearthLevels = new List<HearthLevelData>();
        public List<long> WarehouseStorage = new List<long>();
        public double SilverShare;
        public RulesData Rules = new RulesData();
        public BuildData Build = new BuildData();
        public double OfflineCapHours;
        public StarterData Starter = new StarterData();
        public WarmthData Warmth = new WarmthData();
        public List<HearthModeData> HearthModes = new List<HearthModeData>();
        public double CoalPerWarmthHour;
        public double FoodPerDwellerHour;
        public DwellerData Dwellers = new DwellerData();
        public HeroData Heroes = new HeroData();
        public List<long[]> SpeedupPoints = new List<long[]>();
        public ProductionData Production = new ProductionData();
        public List<RoomData> Rooms = new List<RoomData>();
        public GridData Grid = new GridData();
        /// <summary>GDD 10: hearth levels that open the 6th-9th squad slots.</summary>
        public int[] SquadSlots = new int[0];
        public ActivitiesData Activities = new ActivitiesData();

        public static Balance FromJson(string json)
        {
            var balance = JsonConvert.DeserializeObject<Balance>(json);
            if (balance == null || balance.HearthLevels.Count != balance.MaxHearthLevel - 1)
                throw new FormatException("balance.json is broken: expected a row for every hearth level");
            return balance;
        }

        /// <summary>Row of hearth level L (1-based): room jobs to level L and the hearth job L -> L+1.</summary>
        public HearthLevelData Level(int level)
        {
            if (level < 1 || level > HearthLevels.Count)
                throw new ArgumentOutOfRangeException(nameof(level));
            return HearthLevels[level - 1];
        }

        public RoomData Room(RoomType type)
        {
            foreach (var room in Rooms)
            {
                if (room.Type == type)
                    return room;
            }
            throw new KeyNotFoundException(type.ToString());
        }

        public HearthModeData Mode(HearthMode mode)
        {
            foreach (var m in HearthModes)
            {
                if (m.Mode == mode)
                    return m;
            }
            throw new KeyNotFoundException(mode.ToString());
        }

        /// <summary>Silver + iron the warehouse holds at this warehouse level.</summary>
        public long StorageAt(int warehouseLevel)
        {
            int i = Math.Max(1, Math.Min(warehouseLevel, WarehouseStorage.Count)) - 1;
            return WarehouseStorage[i];
        }

        public double ProductionBase(ResourceType resource, int roomLevel)
        {
            var table = Production.Base[resource.ToString()];
            int i = Math.Max(1, Math.Min(roomLevel, table.Length)) - 1;
            return table[i];
        }
    }

    public sealed class HearthLevelData
    {
        public int Level;
        public long HearthSeconds;
        public long RoomSeconds;
        public long RoomJobCost;
        public long HearthJobCost;
        public long Storage;
        public int Builders;
        public RoomType KeyRoom;
        public int HeroRequirement;
    }

    public sealed class RulesData
    {
        public int StorageGateFrom;
        public int HeroGateFrom;
        public int HeroCore;
    }

    public sealed class BuildData
    {
        public int QueuePerBuilder;
        public long FreeFinishSeconds;
    }

    public sealed class StarterData
    {
        public long Materials;
        public long Essence;
        public long Coal;
        public long Food;
    }

    public sealed class WarmthData
    {
        public double Base;
        public double PerLevel;
        public double FloorFalloff;
        public double RoomNeedBase;
        public double RoomNeedGrowth;
        public double FrozenOutput;
    }

    public sealed class HearthModeData
    {
        public HearthMode Mode;
        public double Coal;
        public double Warmth;
        public double Output;
    }

    public sealed class DwellerData
    {
        public int CapBase;
        public int CapPerLevel;
    }

    public sealed class HeroData
    {
        public double LevelCostBase;
        public double LevelCostGrowth;
        public int CapBase;
        public int CapPerHearth;
    }

    public sealed class ProductionData
    {
        public double StatDivisor;
        public int WorkersPerRoom;
        public Dictionary<string, double[]> Base = new Dictionary<string, double[]>();
    }

    public sealed class RoomData
    {
        public RoomType Type;
        public string Name;
        public int Unlock;
        public ResourceType? Produces;
        public Stat? Stat;
        public int MaxCount;
    }

    /// <summary>ACTIVITIES.md: Surge, Hunt and Routes with their own resources. Tables are by hearth level 1-30.</summary>
    public sealed class ActivitiesData
    {
        public SurgeData Surge = new SurgeData();
        public HeartData Heart = new HeartData();
        public HuntData Hunt = new HuntData();
        public SkillData Skills = new SkillData();
        public LegendaryData Legendary = new LegendaryData();
        public RouteData Routes = new RouteData();
        public SpecializationData Specializations = new SpecializationData();
    }

    public sealed class SurgeData
    {
        public int Unlock;
        public double AutoShare;
        public int[] EmberByLevel = new int[0];
    }

    public sealed class HeartData
    {
        public int[] NodeCost = new int[0];
        public int[] NodeGate = new int[0];
    }

    public sealed class HuntData
    {
        public int Unlock;
        public int TracksPerDay;
        public int TrackHours;
        public int[] CoresByLevel = new int[0];
    }

    public sealed class SkillData
    {
        public int Max;
        public int HeroLevelsPerSkill;
        public int[] Cost = new int[0];
    }

    public sealed class LegendaryData
    {
        public int FromHearth;
        public int Cores;
    }

    public sealed class RouteData
    {
        public int Unlock;
        public int[] SquadsByLevel = new int[0];
        public int[] BlueprintsByLevel = new int[0];
    }

    public sealed class SpecializationData
    {
        public List<int[]> Tiers = new List<int[]>();
        public int Ranks;
        public int RanksFromHearth;
    }

    public sealed class GridData
    {
        public int Floors;
        public int Cells;
        public int HearthFloor;
        public int[] HearthCells = new int[0];
    }
}
